class ProfileReloadDiscardContracts(unittest.TestCase):
    def test_exact_inverse_restores_the_entire_original_profile_view(self):
        raw=VIEW.read_bytes();self.assertEqual(sha(raw),INVERSE['after'])
        for offset,after,before in reversed(INVERSE['hunks']):
            self.assertEqual(raw[offset:offset+len(after)],after);raw=raw[:offset]+before+raw[offset+len(after):]
        self.assertEqual(sha(raw),INVERSE['before'])
    def test_other_former_muse_paths_core_transports_catalog_and_existing_tests_unchanged(self):
        for path,expected in PROTECTED.items():self.assertEqual(sha((ROOT/path).read_bytes()),expected,path)
    def test_only_explicit_reload_entry_uses_the_new_confirmation(self):
        text=VIEW.read_text();self.assertEqual(text.count('Task { await model.requestReload() }'),1)
        self.assertIn('await self.load()',text);self.assertIn('if loaded, let snapshot = coordinator.snapshot { draft = snapshot.draft }',text)
        self.assertIn('await model.resetAndLoad()',text)
    def test_dirty_draft_gate_covers_exact_text_bytes_and_optional_preference_wire_value(self):
        text=VIEW.read_text().split('private var hasUnsavedDraft: Bool')[1].split('func cancelReload()')[0]
        self.assertIn('draft.name.utf8.elementsEqual(snapshot.nickname.utf8)',text)
        self.assertIn('draft.introduction.utf8.elementsEqual(snapshot.introduction.utf8)',text)
        self.assertIn('draft.routePreferenceIDs.map',text);self.assertIn('?? true',text)
        self.assertNotIn('normalized',text);self.assertNotIn('trimmingCharacters',text)
    def test_locked_unknown_write_reconciliation_bypasses_discard_review(self):
        text=VIEW.read_text().split('func requestReload() async')[1].split('private func canReload')[0]
        self.assertIn('guard !coordinator.isLocked, hasUnsavedDraft else { await load(); return }',text)
        self.assertNotIn('.save(',text);self.assertNotIn('prepare(',text)
    def test_cancel_performs_no_read_and_changes_no_draft(self):
        text=VIEW.read_text();self.assertIn('func cancelReload() { reloadConfirmation = nil }',text)
        self.assertIn('Button("action.cancel", role: .cancel) { model.cancelReload() }',text)
    def test_confirmation_consumes_synchronously_and_queued_task_rechecks(self):
        text=VIEW.read_text().split('@discardableResult func confirmReload')[1].split('private func synchronizeContext')[0]
        self.assertIn('guard reloadConfirmation?.id == value.id else { return nil }',text)
        self.assertLess(text.index('reloadConfirmation = nil'),text.index('return Task'))
        self.assertIn('guard let self, !Task.isCancelled, self.canReload(value)',text)
        self.assertEqual(text.count('await self.load()'),1)
    def test_all_owner_draft_snapshot_and_review_fences_are_checked(self):
        text=VIEW.read_text().split('private func canReload')[1].split('/// Consume')[0]
        for part in ['!busy','!coordinator.isBusy','!coordinator.isLocked','coordinator.isConfigured','confirmation == nil','coordinator.confirmation == nil','coordinator.identity == value.identity','coordinator.viewerRevision == value.viewerRevision','generation == value.generation','revision == value.modelRevision','reloadContextRevision == value.reloadContextRevision','Self.sameDraft(draft, value.draft)','Self.sameSnapshot(snapshot, value.snapshot)']:
            self.assertIn(part,text)
    def test_draft_aba_scene_departure_and_session_change_retire_context(self):
        text=VIEW.read_text();self.assertIn('@Published var draft = ProfileEditDraft() { didSet { retireReload() } }',text)
        self.assertIn('reloadContextRevision &+= 1',text)
        self.assertIn('.onChange(of: sessionRevision) { _, _ in model.retireReload() }',text)
        self.assertIn('if phase != .active { model.retireReload() }',text)
        self.assertIn('.onDisappear {\n            model.retireReload()',text)
        self.assertIn('.onChange(of: showReloadConfirmation) { _, showing in if !showing { model.cancelReload() } }',text)
    def test_save_review_paths_retire_only_new_reload_dialog(self):
        text=VIEW.read_text()
        for part in ['func load() async {\n        retireReload()','func prepare() async {\n        retireReload()','func save(_ value: ProfileEditConfirmation) async {\n        retireReload()']:
            self.assertIn(part,text)
        self.assertIn('await coordinator.prepare(draft)',text);self.assertIn('await coordinator.save(value)',text)
    def test_three_localizations_are_complete_and_separate(self):
        fragment=json.loads((ROOT/'Resources/ProfileReloadDiscardLocalizations.fragment.json').read_text())
        catalog=json.loads((ROOT/'Resources/Localizable.xcstrings').read_text())['strings']
        self.assertEqual(len(fragment),3);self.assertFalse(set(fragment)&set(catalog))
        for key,row in fragment.items():
            self.assertIn('"'+key+'"',VIEW.read_text())
            for lang in ['en','zh-Hans']:self.assertTrue(row['localizations'][lang]['stringUnit']['value'])
    def test_twenty_authored_tests_cover_cancel_failure_exact_context_and_unknown_lock(self):
        text=(ROOT/'Tests/AppUnitTests/ProfileReloadDiscardTests.swift').read_text();self.assertEqual(len(re.findall(r'func test',text)),20)
        for part in ['CancelPreservesAllBytes','FailedConfirmedReload','CanonicalUnicodeByteChanges','DraftABA','AnotherOwner','ViewerRevisionChanges','SignOutRejectsQueued','UnknownWriteReconciliation','StaleDialogCannotConsumeOrCancelNewer']:
            self.assertIn(part,text)
if __name__=='__main__':unittest.main()
